findings.fix:
 // Pull pattern: O(1) per user, no loop, cannot be griefed.
+function claim() external nonReentrant {
+    _updateReward(msg.sender);
+    uint256 amount = pending[msg.sender];
+    pending[msg.sender] = 0;
+    rewardToken.safeTransfer(msg.sender, amount);
+}

 // If a loop is unavoidable, paginate and cache the bound:
+function distribute(uint256 start, uint256 end) external onlyOwner {
+    uint256 len = stakers.length;
+    if (end > len) end = len;
+    for (uint256 i = start; i < end;) {
+        pending[stakers[i]] += share(stakers[i]);
+        unchecked { ++i; }
+    }
+}

